import { P_VIEWPORT } from '../private.js';
export class XRViewport {
  constructor(x, y, width, height) {
    this[P_VIEWPORT] = {
      x,
      y,
      width,
      height
    };
  }
  get x() {
    return this[P_VIEWPORT].x;
  }
  get y() {
    return this[P_VIEWPORT].y;
  }
  get width() {
    return this[P_VIEWPORT].width;
  }
  get height() {
    return this[P_VIEWPORT].height;
  }
}